from pathlib import Path
import html
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'materials/exercises/第04回_角測量'
STYLE='''body{font:16px/1.65 "Yu Gothic",Meiryo,sans-serif;color:#182b33;max-width:900px;margin:30px auto;padding:0 24px}h1{font-size:26px}h2{font-size:21px;color:#166b68}table{width:100%;border-collapse:collapse;margin:15px 0}th,td{border:1px solid #b7c4c8;padding:8px;text-align:center}th{background:#eef5f4}.blank{height:58px}.space{height:100px;border-bottom:1px solid #cfd9dd}.small{font-size:13px}svg{max-width:100%;height:auto}button,a{font:inherit;color:#166b68}button{padding:9px 18px;background:white;border:1px solid #166b68;cursor:pointer}.page{padding-bottom:30px}@media(max-width:600px){body{font-size:14px;padding:0 12px}.tablewrap{overflow-x:auto}table{white-space:nowrap}}@media print{@page{size:A4;margin:14mm}body{font-size:10.5pt;margin:0;padding:0;max-width:none}h1{font-size:18pt}h2{font-size:14pt}.page{break-after:page;padding:0}.page:last-child{break-after:auto}button,.nav{display:none}th,td{padding:6px}.space{height:25mm}table,svg{break-inside:avoid}}'''
def table(headers,rows):
    return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def doc(title,body):return '<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+STYLE+'</style><body><button onclick="print()">印刷する</button>'+body+'</body></html>'
raw=table(['対回','方向','正 r','反 l'],[['1','A','5°00′10″','185°00′14″'],['1','B','67°14′28″','247°14′28″'],['1','C','133°32′30″','313°32′30″'],['2','A','95°00′20″','275°00′16″'],['2','B','157°14′36″','337°14′30″'],['2','C','223°32′44″','43°32′44″']])
calc=table(['対回・方向','正の結果p','反の結果q','倍角D','較差C'],[['1・B（例）','62°14′18″','62°14′14″','124°28′32″','＋4″'],['2・B','　　　　','　　　　','　　　　','　　'],['1・C','　　　　','　　　　','　　　　','　　'],['2・C','　　　　','　　　　','　　　　','　　']])
checks=table(['方向','倍角差','観測差','採否と理由／採用する角'],[['B','　　','　　','　　　　　　　　　'],['C','　　','　　','　　　　　　　　　']])
fig='''<svg viewBox="0 0 650 250" width="650" height="230" role="img" aria-label="O E Bが一直線、EからAへ垂直、OE1mとEA100m。Oの角とOAを求める"><g fill="none" stroke-width="3"><path d="M140 190L240 30M140 190H520" stroke="#166b68"/><path d="M240 30V190M240 170H260V190" stroke="#a94737"/></g><g font-size="20" font-family="Meiryo"><text x="110" y="220">O</text><text x="230" y="220">E</text><text x="530" y="197">B</text><text x="230" y="25">A</text><text x="280" y="104">EA＝100m</text><text x="160" y="238">OE＝1m</text><text x="45" y="104">OA＝？</text><text x="275" y="180">90°</text></g></svg>'''
body='''<section class="page"><h1>第4回 角測量「回2」— 演習</h1><p>25分・10点／関数電卓はDEG。途中式を残し、最後に丸める。</p><h2>問1　方向法の採否（15分・6点）</h2><p>各対回でAを零方向とする。正と反で別々にAを引き、負なら360°を加える。</p>'''+raw+'''<p><strong>授業用の仮基準：</strong>倍角差10″以下、観測差8″以下。ちょうどの値は範囲内。公共測量の規程値ではない。</p><p>①空欄を埋める。D＝p＋q、C＝p−q。第1対回Bは記入例。</p>'''+calc+'''<p>②同じ方向のDとCの最大−最小を求める。採用できる方向のみ、2対回の平均角を0.1″まで示す。採用できない場合は理由と対応を書く。</p>'''+checks+'''<p class="small">生読定は正r・反l、零方向差引き後の結果はp・q。表は目標ごとに並べた簡略野帳で、A閉・帰零差は今回扱わない。</p></section>
<section class="page"><h1>第4回 角測量「回2」— 演習 2/2</h1><h2>問2　中心の角と距離へ戻す（10分・4点）</h2><p>O→E→Bはこの順に一直線。器械をEに置き、EからAを図の上向きに見る。OE＝1m、EA＝100m、EでAからBへの時計回り角は90°だった。中心Oでの値を求める。</p>'''+fig+'''<p class="small">OEは誇張し、図は縮尺どおりではない。Aの中心座標とOの角は与えていない。</p><p>① 中心OでAからBへの時計回り角を、0.1″まで求める。（1.5点）</p><div class="space"></div><p>② OAを小数第4位のmまで求める。（1点）</p><div class="space"></div><p>③ 角とAまでの距離の補正を、符号とともに示す。<br>補正＝中心Oの値−Eでの値。（1.5点）</p><div class="space"></div><p class="small">電卓がない場合：tan⁻¹(1/100)＝0.5729386977°を使ってよい。中心角の求め方と距離は自分で判断する。</p></section>'''
(OUT/'exercise_回2.html').write_text(doc('角測量 回2 演習',body),encoding='utf-8')
answers='''<section class="page"><h1>第4回 角測量「回2」— 別紙解答</h1><h2>問1　Bを採用、Cは再測</h2>'''+table(['対回・方向','正の結果p','反の結果q','倍角D','較差C'],[['1・B','62°14′18″','62°14′14″','124°28′32″','＋4″'],['2・B','62°14′16″','62°14′14″','124°28′30″','＋2″'],['1・C','128°32′20″','128°32′16″','257°04′36″','＋4″'],['2・C','128°32′24″','128°32′28″','257°04′52″','−4″']])+'''<p>第2対回の反C：43°32′44″＋360°−275°00′16″＝128°32′28″。</p>'''+table(['方向','倍角差','観測差','判定'],[['B','2″','2″','両方範囲内'],['C','16″','8″','倍角差が超過']])+'''<p>Bの角は第1対回62°14′16″、第2対回62°14′15″。採用値は<strong>62°14′15.5″</strong>。Cの観測差8″は境界内だが、倍角差16″が超過するためCの平均を採用値にしない。原因を確認し、零方向など必要な関連観測を含め、適用する方法に従って再測する。</p>
<h2>問2　直角はE、斜辺はOA</h2><p>δ＝tan⁻¹(1/100)＝0.572938697683…°。</p><p>① ∠AOB＝90°−δ＝89.4270613023…°＝<strong>89°25′37.4″</strong>。</p><p>② OA＝√(100²＋1²)＝100.004999875…m → <strong>100.0050m</strong>。</p><p>③ 角補正＝−δ＝<strong>−0°34′22.6″</strong>。距離補正＝OA−100＝<strong>＋0.0050m</strong>。</p><p>講義デモではOが直角でEAが斜辺だった。今回はEが直角でOAが斜辺なので、距離補正の符号が逆になる。</p></section>
<section class="page"><h1>採点基準・授業時の支援</h1>'''+table(['問','観点','点'],[['1','p・q：未記入3行の計6値（連鎖誤差は別扱い）','2.0'],['1','倍角D・較差C：3行','1.0'],['1','B・Cの倍角差・観測差','1.0'],['1','Bの平均角','0.5'],['1','B採用、C再測と超過理由','1.5'],['2','中心角の式・値','1.5'],['2','OAの式・値','1.0'],['2','角補正と距離補正の符号・量','1.5']])+'''<p>問1のp/qは6値のうち6値正解2点、4–5値1.5点、2–3値1点、1値0.5点を目安とする。以後の一貫した計算は、最初の計算ミスを重複して減点しない。ただし採否の論理が成立しているかを別に見る。較差の符号、観測差の定義、Cの平均を採用しない判断を重視する。</p><p>角は0.1″、距離は0.0001mへ最後に丸める。正しい式がある丸め誤差は段階に応じて部分点。電卓支援値を0.5729°に短縮すると角秒の丸めがずれるため、指定の桁数を提示する。</p><p>問1の開始5分後に零方向差引きを確認。15分で問2へ移行。時間が不足しても別の10分テストを追加せず、出口問題で理由を口頭確認する。</p><p class="nav"><a href="exercise_回2.html">問題に戻る</a></p></section>'''
(OUT/'exercise_answers_回2.html').write_text(doc('角測量 回2 別紙解答',answers),encoding='utf-8')
print('問題・別紙解答HTMLを作成')
